function toast(message){const node=$('#toast');node.textContent=String(message);node.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.remove('show'),3600)}
function englishName(zh){if(!zh)return'';if(exactNames[zh])return exactNames[zh];if(provinceNames[zh])return provinceNames[zh];const short=zh.replace(zhSuffix,'');if(pinyinFn){const words=pinyinFn(short,{toneType:'none',type:'array'});const roman=words.map(word=>word.charAt(0).toUpperCase()+word.slice(1)).join(' ');return roman+' '+zh}return 'China destination '+zh}
function cityKeyFromDestination(value){return Object.keys(destinationProfiles).find(key=>value.includes(key)||value.includes(destinationProfiles[key].zh))}
function genericProfile(destination){const english=destination.split(/\s(?=[\u3400-\u9fff])/)[0]||destination;return{zh:destination.match(/[\u3400-\u9fff]+/)?.[0]||'',mood:'LOCAL CHINA · DISCOVERY',description:'Explore '+english+' through its best-known landscapes, local culture and everyday flavors. Each stop is marked for live map verification before booking.',sights:[`Official landmark in ${destination}`,`Local cultural site in ${destination}`,`Signature natural scenery near ${destination}`,`Historic neighborhood in ${destination}`,`Local craft or food experience in ${destination}`,`Easy day trip from ${destination}`],foods:[`Local breakfast in ${destination}`,`Regional specialty meal in ${destination}`,`Local tea or dessert in ${destination}`],stay:`Central ${destination}, close to the main transport hub`}}
function getProfile(destination){const key=cityKeyFromDestination(destination);return key?destinationProfiles[key]:genericProfile(destination)}

