let currentFlowStep=0,maxUnlockedFlowStep=1;
function unlockFlow(step){maxUnlockedFlowStep=Math.max(maxUnlockedFlowStep,step)}
function showFlowStep(step){
  if(step<=6&&step>maxUnlockedFlowStep){toast('Complete the current step before moving ahead.');return}
  currentFlowStep=step;document.body.classList.add('flow-mode');document.body.dataset.flowStep=String(step);
  $$('.journey-axis button').forEach(button=>{const value=+button.dataset.flowStep;button.disabled=value>maxUnlockedFlowStep;button.classList.toggle('active',value===step);button.classList.toggle('complete',value<step&&value<=maxUnlockedFlowStep)});
  $('#axisProgress').style.width=`${Math.min(step,6)/6*100}%`;window.scrollTo({top:0,behavior:'smooth'});
}
