function tripInput(){const start=new Date($('#startDate').value),end=new Date($('#endDate').value);const days=Math.max(1,Math.round((end-start)/86400000)+1);const destination=$('#destination').value;return{destination,location:{province:$('#province').value,city:$('#prefecture').value,county:$('#county').value||null,path:[$('#province').value,$('#prefecture').value,$('#county').value].filter(Boolean)},startDate:$('#startDate').value,endDate:$('#endDate').value,days,travelers:Math.max(1,+$('#travelers').value||1),budget:$('#budget').value,transport:$('#transport').value,origin:$('#origin').value.trim()||'your arrival point',interests:$$('#interestChips input:checked').map(input=>input.value),principles:[...travelPrinciples],notes:$('#notes').value.trim(),mustDo:$('#mustDo')?.value.trim()||'',profile:getProfile(destination)}}
const baseTripInput=tripInput;tripInput=function(){const input=baseTripInput(),dailyStartTime=$('#dailyStartTime').value,dailyEndTime=$('#dailyEndTime').value,dailyPace=$('#dailyPace').value,itineraryDetail=$('input[name="itineraryDetail"]:checked').value;input.dailyWindow={start:dailyStartTime,end:dailyEndTime};input.dailyPace=dailyPace;input.itineraryDetail=itineraryDetail;input.notes=[input.notes,`Daily travel window: ${dailyStartTime} to ${dailyEndTime}.`,`Daily pace: ${dailyPace}.`,`Itinerary detail: ${itineraryDetail}.`].filter(Boolean).join(' ');return input};
function formatEstimatedCost(value){if(typeof value==='string')return value;if(typeof value==='number')return money(value);if(value&&typeof value==='object')return Object.entries(value).map(([key,item])=>`${key.replaceAll('_',' ')}: ${typeof item==='object'?JSON.stringify(item):item}`).join(' · ');return'Verify before booking'}
function compactEstimatedCost(value){
  const text=String(value||'Verify before booking').replace(/\s+/g,' ').trim();
  const amount=text.split(/\s*·\s*|\s*\|\s*|\s+basis\s*:/i)[0]
    .replace(/^(?:estimated\s+)?(?:trip\s+)?(?:cost\s+)?range\s*:\s*/i,'')
    .trim();
  return amount||'Verify before booking';
}
function normalizeAiRoute(route,input,index){const rawDays=Array.isArray(route.daily_plan)?route.daily_plan:[];const days=Array.from({length:input.days},(_,i)=>{const raw=rawDays[i]||{},rawActivities=Array.isArray(raw.activities)?raw.activities:[raw.morning,raw.afternoon,raw.evening].filter(Boolean),activities=rawActivities.map(activity=>typeof activity==='string'?activity:[activity?.time,activity?.title||activity?.activity,activity?.description].filter(Boolean).join(' · ')).filter(Boolean),a=activities[0]||raw.title||'Local exploration',b=activities[1]||activities[2]||'Flexible time and transfer buffer',timeline=activities.map((activity,activityIndex)=>[`Stop ${activityIndex+1}`,activity]);if(raw.transport)timeline.push(['Transport',raw.transport]);if(raw.meals)timeline.push(['Meals',raw.meals]);if(raw.summary)timeline.push(['Day note',raw.summary]);return{a,b,food:raw.meals||'Local specialties',cost:{transport:0,stay:0,food:0,sights:0,total:0},timeline:timeline.length?timeline:[['Plan',`${a}; ${b}`]]}});return{name:route.title||`Personal route ${index+1}`,label:['PERSONALIZED','LOCAL DEPTH','EASY PACE'][index]||'PERSONAL ROUTE',summary:route.description||'A personalized route based on your choices.',days,aiRoute:route,estimatedCost:formatEstimatedCost(route.estimated_cost),tips:route.tips}}
function renderAiRoutes(input,routes){currentPlans=routes.slice(0,3).map((route,index)=>normalizeAiRoute(route,input,index));$('#resultsIntro').textContent=`${input.days} days in ${input.destination} · ${input.travelers} traveler${input.travelers>1?'s':''} · Priority: ${input.principles[0]||'your preferences'}`;$('#routeGrid').innerHTML=currentPlans.map((plan,index)=>`<article class="route-card ${index===0?'featured':''}"><span class="route-badge">${esc(plan.label)}</span><p class="kicker">${String(index+1).padStart(2,'0')} / ITINERARY</p><h3>${esc(plan.name)}</h3><p>${esc(plan.summary)}</p><div class="route-facts"><span>Daily plan <b>${input.days} days</b></span><span>Transport <b>${esc(input.transport)}</b></span><span>Cost <b>${esc(typeof plan.estimatedCost==='string'?plan.estimatedCost:'See plan')}</b></span></div><ol class="route-preview">${plan.days.slice(0,3).map((day,dayIndex)=>`<li>Day ${dayIndex+1}: ${esc(day.a)}</li>`).join('')}</ol><p class="route-price">${esc(Array.isArray(plan.tips)?plan.tips.join(' · '):(plan.tips||''))}</p><button class="primary select-route" data-plan="${index}" type="button">Choose this itinerary <span>→</span></button></article>`).join('');$$('.select-route').forEach(button=>button.addEventListener('click',()=>selectRoute(+button.dataset.plan,input)));$('#results').classList.remove('hidden');$('#finalPlan').classList.add('hidden');$('#results').scrollIntoView({behavior:'smooth'})}
function selectRoute(index,input){
  unlockFlow(6);showFlowStep(6);selectedPlan=currentPlans[index];
  const totals=selectedPlan.days.reduce((sum,day)=>{Object.keys(sum).forEach(key=>sum[key]+=day.cost[key]);return sum},{transport:0,stay:0,food:0,sights:0,total:0});
  Object.keys(totals).forEach(key=>totals[key]*=input.travelers);
  $('#finalSubtitle').textContent=`${selectedPlan.name} · ${input.days} days · ${input.destination}`;
  $('#budgetStrip').classList.toggle('ai-budget',Boolean(selectedPlan.aiRoute));
  $('#budgetStrip').innerHTML=selectedPlan.aiRoute
    ?[['Estimated trip cost',compactEstimatedCost(selectedPlan.estimatedCost)],['Travelers',String(input.travelers)],['Planning basis','Conservative estimate']].map(item=>`<div class="budget-item"><small>${item[0]}</small><b>${esc(item[1])}</b></div>`).join('')
    :[['Transport',totals.transport],['Stays',totals.stay],['Food',totals.food],['Sights',totals.sights],['Trip total',totals.total]].map(item=>`<div class="budget-item"><small>${item[0]}</small><b>${money(item[1])}</b></div>`).join('');
  $('#dayList').innerHTML=selectedPlan.days.map((day,dayIndex)=>`<article class="day-card"><div class="day-index"><small>DAY</small>${String(dayIndex+1).padStart(2,'0')}</div><div><h3>${esc(day.a)} + ${esc(day.b)}</h3><div class="timeline">${day.timeline.map(row=>`<div class="timeline-row"><b>${row[0]}</b><span>${esc(row[1])}</span></div>`).join('')}</div><div class="day-meta">${selectedPlan.aiRoute?`<div><b>Transport</b>${esc(input.transport)}</div><div><b>Stay area</b>${esc(input.profile.stay)}</div><div><b>Meals</b>${esc(day.food)}</div>`:`<div><b>Transport</b>${esc(input.transport)} · ${money(day.cost.transport*input.travelers)}</div><div><b>Stay</b>${esc(input.profile.stay)} · ${money(day.cost.stay*input.travelers)}</div><div><b>Food + sights</b>${money((day.cost.food+day.cost.sights)*input.travelers)}</div>`}</div></div></article>`).join('');
  $('#mapCheck').href='https://uri.amap.com/search?keyword='+encodeURIComponent(input.destination)+'&src=china-trip-planner';
  $('#finalPlan').classList.remove('hidden');$('#finalPlan').scrollIntoView({behavior:'smooth'});saveChosenPlan(input,selectedPlan,totals);toast('Your detailed China itinerary is ready.');
}
let generatingRoutes=false;
$('#tripForm').addEventListener('submit',async event=>{
  event.preventDefault();
  if(generatingRoutes)return;
  if(!$('#province').value||!$('#prefecture').value)return toast('Choose a province and city first.');
  const input=tripInput();
  if(!input.startDate||!input.endDate||input.days<1)return toast('Choose valid travel dates.');
  generatingRoutes=true;
  const submit=event.submitter;
  if(submit)submit.disabled=true;
  showRouteGeneration();
  const controller=new AbortController();
  const timeout=setTimeout(()=>controller.abort(),55000);
  try{
    const response=await fetch('/api/deepseek',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input),signal:controller.signal});
    const raw=await response.text();
    let payload;
    try{payload=raw?JSON.parse(raw):{}}catch{throw new Error(location.hostname==='localhost'?'This local address is not running the route-planning function. Start the site with netlify dev and open the URL it prints.':`The route planner returned an invalid server response (${response.status}). Please try again.`)}
    if(!response.ok)throw new Error(payload.error||`Route planning failed (${response.status}). Please try again.`);
    if(!Array.isArray(payload.routes)||payload.routes.length!==3)throw new Error('The route planner did not return all three itineraries. Please try again.');
    renderAiRoutes(input,payload.routes);
    unlockFlow(5);
    showFlowStep(5);
  }catch(error){
    console.error(error);
    toast(error.name==='AbortError'?'Route planning took too long. Please try once more.':error.message||'Route planning failed. Please try again.');
  }finally{
    clearTimeout(timeout);
    generatingRoutes=false;
    if(submit)submit.disabled=false;
    hideRouteGeneration();
  }
});
$('#editTrip').addEventListener('click',()=>showFlowStep(2));
$('#revisePreferences').addEventListener('click',()=>{renderAdvancedPreferences();showFlowStep(4)});

function localPlans(){try{return JSON.parse(localStorage.getItem('chinaTripPlans')||'[]')}catch{return[]}}
function renderSaved(plans=localPlans()){if(!plans.length){if(currentUser){$('#savedTrips').className='empty-state';$('#savedTrips').innerHTML='<p>No cloud trips yet. Choose an itinerary and it will appear here on every device.</p>'}return}$('#savedTrips').className='';$('#savedTrips').innerHTML=plans.map(plan=>`<article class="saved-trip"><div><b>${esc(plan.destination)}</b><br><small>${esc(plan.name)} · ${plan.days} days · ${new Date(plan.savedAt).toLocaleDateString('en-US')}</small></div><span>${money(plan.total)}</span></article>`).join('')}
function setPreferenceCloudStatus(message,state=''){const node=$('#priorityCloudStatus');if(!node)return;node.textContent=message;node.dataset.state=state}
function preferencePayload(){return{user_id:currentUser.id,planning_priorities:[...travelPrinciples],updated_at:new Date().toISOString()}}
async function persistUserPreferences(){if(!currentUser||!supabase||preferencesLoadedFor!==currentUser.id)return false;setPreferenceCloudStatus('Saving preferences to your account…','saving');const {error}=await supabase.from('user_travel_preference_settings').upsert(preferencePayload(),{onConflict:'user_id'});if(error){console.warn('Preference sync failed.',error);setPreferenceCloudStatus('Could not save. Nothing was changed in your account.','error');return false}setPreferenceCloudStatus('Saved to your account. These preferences will return on your next sign-in.','saved');return true}
async function loadUserPreferences(){if(!currentUser||!supabase)return;setPreferenceCloudStatus('Loading your saved priorities…','loading');const userId=currentUser.id,{data,error}=await supabase.from('user_travel_preference_settings').select('planning_priorities').eq('user_id',userId).maybeSingle();if(currentUser?.id!==userId)return;if(error){console.warn('Preference load failed.',error);preferencesLoadedFor=userId;setPreferenceCloudStatus('Cloud priorities are temporarily unavailable.','error');return}if(Array.isArray(data?.planning_priorities)&&data.planning_priorities.length)travelPrinciples=[...data.planning_priorities];renderAdvancedPreferences();preferencesLoadedFor=userId;setPreferenceCloudStatus(data?'Saved priorities restored from your account.':'Changes here will be saved to your account automatically.',data?'saved':'ready')}
async function loadCloudPlans(){if(!currentUser||!supabase)return;const userId=currentUser.id,{data,error}=await supabase.from('user_travel_plan_history').select('id,destination,route_name,plan_data,created_at').eq('user_id',userId).order('created_at',{ascending:false}).limit(50);if(currentUser?.id!==userId)return;if(error){console.warn('Cloud trip history unavailable.',error);renderSaved();return}const plans=(data||[]).map(row=>{const payload=row.plan_data||{},input=payload.input||{},plan=payload.plan||{},totals=payload.totals||{};return{destination:row.destination,name:row.route_name,days:input.days||plan.days?.length||1,total:totals.total||0,savedAt:row.created_at}});renderSaved(plans)}
async function saveChosenPlan(input,plan,totals){const record={destination:input.destination,name:plan.name,days:input.days,total:totals.total,savedAt:new Date().toISOString()};const existing=localPlans().filter(item=>!(item.destination===record.destination&&item.name===record.name));localStorage.setItem('chinaTripPlans',JSON.stringify([record,...existing].slice(0,8)));renderSaved();if(currentUser&&supabase){const {error}=await supabase.from('user_travel_plan_history').insert({user_id:currentUser.id,destination:input.destination,route_name:plan.name,plan_data:{input,plan,totals}});if(error){console.warn('Cloud save unavailable; plan remains saved on this device.',error);return}await loadCloudPlans()}}

function openAuth(){if(currentUser){toast('You are already signed in.');return}$('#authDialog').showModal()}$('#authButton').addEventListener('click',openAuth);$('#savedAuthButton').addEventListener('click',openAuth);
function setAuthMode(mode){authMode=mode;$$('[data-auth-mode]').forEach(button=>button.classList.toggle('active',button.dataset.authMode===mode));$('#confirmLabel').classList.toggle('hidden',mode!=='register');$('#authSubmit').textContent=mode==='register'?'Create account':'Sign in';$('#authStatus').textContent=''}$$('[data-auth-mode]').forEach(button=>button.addEventListener('click',()=>setAuthMode(button.dataset.authMode)));
async function initAuth(){try{const module=await import('https://esm.sh/@supabase/supabase-js@2.57.4');supabase=module.createClient('https://snsfmpcomwkrqcofbssa.supabase.co','sb_publishable_bDB5kn2d3f9azvxvGlDMfg_HSoZSD84');const {data}=await supabase.auth.getSession();if(data.session)await showUser(data.session.user);supabase.auth.onAuthStateChange((_event,session)=>{if(session&&session.user.id!==currentUser?.id)void showUser(session.user)})}catch(error){console.warn('Account service unavailable; trip planning still works.',error);setPreferenceCloudStatus('Account sync is temporarily unavailable.','error')}}
async function showUser(user){currentUser=user;const name=user.user_metadata?.username||'Traveler';$('#authButton').textContent=name+' · Signed in';if($('#authDialog').open)$('#authDialog').close();await Promise.all([loadUserPreferences(),loadCloudPlans()]);toast('Welcome back, '+name+'.')}
$('#authForm').addEventListener('submit',async event=>{event.preventDefault();if(!supabase)return $('#authStatus').textContent='Account service is temporarily unavailable. You can still plan as a guest.';const username=$('#username').value.trim(),password=$('#password').value;if(!/^[A-Za-z0-9_]{3,24}$/.test(username))return $('#authStatus').textContent='Use 3–24 letters, numbers or underscores.';if(authMode==='register'&&password!==$('#confirmPassword').value)return $('#authStatus').textContent='Passwords do not match.';$('#authStatus').textContent=authMode==='register'?'Creating your account…':'Signing you in…';const email=username.toLowerCase()+'@travel-planner.app';const result=authMode==='register'?await supabase.auth.signUp({email,password,options:{data:{username}}}):await supabase.auth.signInWithPassword({email,password});if(result.error)return $('#authStatus').textContent=(authMode==='register'?'Account creation failed. ':'Sign-in failed. ')+result.error.message;if(result.data.session&&result.data.user.id!==currentUser?.id)await showUser(result.data.user);else if(!result.data.session) $('#authStatus').textContent='Account created. Sign in to continue.'});

